const loopItems = $('INTERCOM: LOOP').all(); // the 10 rows in this batch
const intercomItems = $input.all();          // previous node: 10 Intercom results

// Safety check: if counts differ, index matching isn't reliable
if (loopItems.length !== intercomItems.length) {
  throw new Error(
    `Item count mismatch: loop=${loopItems.length}, intercom=${intercomItems.length}`
  );
}

return intercomItems.map((item, i) => {
  const row = loopItems[i].json;
  const contact = item.json?.data?.[0] ?? null;

  const externalId = contact?.external_id ?? null;
  const isPublisher = typeof externalId === 'string' && externalId.startsWith('p_');

  return {
    json: {
      row_number: row.row_number,
      name: row.name,
      company: row.company,
      intercom_found: isPublisher,
      intercom_external_id: externalId,
      intercom_email: contact?.email ?? null,
      intercom_name: contact?.name ?? null,
      platform_source: "intercom",
    },
  };
});

const loopItems = $('AC: LOOP').all();   // the 10 rows in this batch
const acItems = $input.all();            // previous node: 10 ActiveCampaign results

// Safety check: if counts differ, index matching isn't reliable
if (loopItems.length !== acItems.length) {
  throw new Error(
    `Item count mismatch: loop=${loopItems.length}, activecampaign=${acItems.length}`
  );
}

// Normalize for comparison: lowercase, strip punctuation and common company suffixes
const normalize = (str) =>
  (str ?? '')
    .toString()
    .toLowerCase()
    .replace(/[.,]/g, '')
    .replace(/\b(ltd|limited|inc|llc|gmbh|ou|co|corp|corporation|publishing)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();

// Pick the closest organization to the company name
const findClosestOrg = (orgs, company) => {
  if (!Array.isArray(orgs) || orgs.length === 0 || !company) return null;

  const target = company.toString().toLowerCase().trim();
  const targetNorm = normalize(company);

  // 1. Exact match (case insensitive)
  const exact = orgs.find((o) => (o.name ?? '').toLowerCase().trim() === target);
  if (exact) return exact;

  // 2. Exact match after normalizing suffixes (e.g. "Exient Publishing Limited" -> "exient")
  const normExact = orgs.find((o) => normalize(o.name) === targetNorm);
  if (normExact) return normExact;

  // 3. Contains match either way, prefer the shortest name (closest in length)
  const partial = orgs
    .filter((o) => {
      const n = (o.name ?? '').toLowerCase();
      return n.includes(target) || (n.length > 0 && target.includes(n));
    })
    .sort((a, b) => a.name.length - b.name.length);

  return partial[0] ?? null;
};

return acItems.map((item, i) => {
  const row = loopItems[i].json;
  const orgs = item.json?.organizations ?? [];
  const org = findClosestOrg(orgs, row.company);

  return {
    json: {
      row_number: row.row_number,
      name: row.name,
      company: row.company,
      activecampaign_found: !!org,
      ac_org_id: org?.id ?? null,
      platform_source: "activecampaign",
    },
  };
});

// Input: array of objects, each with an "accountContacts" array
// Output: flat array of { account, contact }

const input = $input.all().map(i => i.json);

// If the whole array arrives as a single item, unwrap it
const data = input.length === 1 && Array.isArray(input[0]) ? input[0] : input;

const flattened = data.flatMap(item =>
  (item.accountContacts || []).map(ac => ({
    json: {
      account: ac.account,
      contact: ac.contact,
    },
  }))
);

return flattened;

