// 1. Previous node (AC contacts). Handles one item per contact,
//    or a single item containing the whole array.
const prevItems = $input.all();
let records = [];
for (const item of prevItems) {
  const j = item.json;
  if (Array.isArray(j)) records.push(...j);
  else records.push(j);
}

// 2. ACTIVECAMPAIGN LOGIC node
const logicItems = $('ACTIVECAMPAIGN LOGIC').all();
let logicRows = [];
for (const item of logicItems) {
  const j = item.json;
  if (Array.isArray(j)) logicRows.push(...j);
  else logicRows.push(j);
}

// Helpers
const norm = (s) => (s || '').toString().toLowerCase().replace(/\s+/g, ' ').trim();
const str = (v) => (v === null || v === undefined || v === '' ? null : String(v));

// 3. Build lookup: "first last" -> [{ contact, orgIds:Set }]
const byName = new Map();
for (const rec of records) {
  const contact = rec.contact || rec;
  const fullName = norm(`${contact.firstName || ''} ${contact.lastName || ''}`);
  if (!fullName) continue;

  // Collect every account/org id this contact is tied to
  const orgIds = new Set();
  [contact.orgid, contact.organization].forEach((v) => str(v) && orgIds.add(str(v)));
  (rec.accounts || []).forEach((a) => str(a.id) && orgIds.add(str(a.id)));
  (rec.accountContacts || []).forEach((ac) => str(ac.account) && orgIds.add(str(ac.account)));

  if (!byName.has(fullName)) byName.set(fullName, []);
  byName.get(fullName).push({ contact, orgIds });
}

// 4. Match each logic row: name AND account id must both match
const results = logicRows.map((row) => {
  const candidates = byName.get(norm(row.name)) || [];
  const rowOrgId = str(row.ac_org_id);

  let match = null;
  let reason;

  if (candidates.length === 0) {
    reason = 'name_not_found';
  } else if (!rowOrgId) {
    reason = 'no_ac_org_id';
  } else {
    const hit = candidates.find((c) => c.orgIds.has(rowOrgId));
    if (hit) {
      match = hit.contact;
      reason = 'matched';
    } else {
      reason = 'org_mismatch'; // name exists but under a different company
    }
  }

  return {
    json: {
      ...row,
      name_match: !!match,
      activecampaign_email: match ? match.email : null,
      match_reason: reason,
    },
  };
});

return results;

// Pull data from both upstream nodes
const intercomItems = $('INTERCOM FINAL DATA').all().map(i => i.json);
const activecampaignItems = $('ACTIVECAMPAIGN FINAL DATA').all().map(i => i.json);

// Index ActiveCampaign rows by row_number for quick lookup
const acByRow = new Map(
  activecampaignItems.map(item => [item.row_number, item])
);

// Track which row numbers we've handled
const seen = new Set();
const merged = [];

// Start with Intercom rows, attach the matching ActiveCampaign row
for (const ic of intercomItems) {
  const ac = acByRow.get(ic.row_number);
  seen.add(ic.row_number);

  merged.push({
    json: {
      row_number: ic.row_number,
      name: ic.name ?? ac?.name ?? null,
      company: ic.company ?? ac?.company ?? null,
      intercom_email: ic.intercom_email ?? null,
      activecampaign_email: ac?.activecampaign_email ?? null,
    },
  });
}

// Include any ActiveCampaign rows that had no Intercom match
for (const ac of activecampaignItems) {
  if (seen.has(ac.row_number)) continue;

  merged.push({
    json: {
      row_number: ac.row_number,
      name: ac.name ?? null,
      company: ac.company ?? null,
      intercom_email: null,
      activecampaign_email: ac.activecampaign_email ?? null,
    },
  });
}

// Keep output ordered by row number
merged.sort((a, b) => a.json.row_number - b.json.row_number);

return merged;
